// What a `qrCode` draws (`./qr-code`): the pinned library's code at the shared error-correction
// level, inside its quiet zone, and nothing for a text no code can hold. This workspace's own
// `ng test` run executes these assertions against the emitted module.

import { create } from 'qrcode';
import { describe, expect, it } from 'vitest';

import { QR_ERROR_CORRECTION, QR_QUIET_ZONE, qrDrawing } from './qr-code';

describe('qrCode drawing', () => {
  it('draws the library code at the shared error-correction level inside its quiet zone', () => {
    const text = 'https://example.com/orders/42';
    const code = create(text, { errorCorrectionLevel: QR_ERROR_CORRECTION });
    // Level M's two format bits are 00 (ISO/IEC 18004 table 12).
    expect(code.errorCorrectionLevel.bit).toBe(0);
    const drawing = qrDrawing(text)!;
    expect(drawing.side).toBe(code.modules.size + 2 * QR_QUIET_ZONE);
    const dark = Array.from(code.modules.data).filter((module) => module !== 0).length;
    expect(drawing.path.split('z').filter((part) => part !== '').length).toBe(dark);
    expect(drawing.path.startsWith(`M${QR_QUIET_ZONE} ${QR_QUIET_ZONE}h1v1h-1z`)).toBe(true);
  });

  it('draws nothing for an empty text or one no code can hold', () => {
    expect(qrDrawing('')).toBeNull();
    expect(qrDrawing('x'.repeat(8000))).toBeNull();
  });
});
